// HasExecutionRef applies the HasEdge predicate on the "execution_ref" edge.
func HasExecutionRef() predicate.OrganizationExecutionAttempt {
	return predicate.OrganizationExecutionAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ExecutionRefTable, ExecutionRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasExecutionRefWith applies the HasEdge predicate on the "execution_ref" edge with a given conditions (other predicates).
func HasExecutionRefWith(preds ...predicate.OrganizationExecution) predicate.OrganizationExecutionAttempt {
	return predicate.OrganizationExecutionAttempt(func(s *sql.Selector) {
		step := newExecutionRefStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

